      "fact": "compare `inventory_p99_latency_ms` with the same hour last week",
      "status": "not_stated"
    },
    {
      "fact": "Check recent changes",
      "status": "not_stated"
    },
    {
      "fact": "deployctl history inventory --since 2h",
      "status": "not_stated"
    },
    {
      "fact": "A deploy in the last hour makes 'garbage collection pauses' less likely",
      "status": "stated"
    },
    {
      "fact": "Search the logs for the error code this failure logs",
      "status": "not_stated"
    },
    {
      "fact": "kubectl -n discovery logs deploy/inventory --since 15m | grep INV-LAT-501",
      "status": "not_stated"
    },
    {
      "fact": "Compare the service's own processing time with the time spent waiting on postgres-primary",
      "status": "stated"
    }
  ]
}

